        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol());
        String manufacturer = decoder.getManufacturer();
        assertTrue(!manufacturer.isEmpty());
        assertFalse(manufacturer.equals("Unknown"));
    }

